/// Handle an auto-satisfied step (check passed, no prompt needed).
fn handle_auto_satisfied(
    &self,
    eval_result: &EvaluationResult,
    needs_force: bool,
    event_bus: &mut EventBus,
    step_display: &mut dyn StepDisplay,
) -> Result<StepAction> {
